/* ============ MODULE 6: Z-TRANSFORM ============ */
const Z_RULES = [
  {
    name: "n · aⁿ · u[n]  (differentiation in z)",
    tableNum: "az⁻¹", tableDen: "(1 − az⁻¹)²",
    re: /^n\*(-?\d+\.?\d*)\^n\*u\[n\]$/,
    build: (m) => {
      const a = parseFloat(m[1]);
      return { params: `a = ${a}`, num: `${a}z`, den: `(z − ${a})²`, roc: `|z| > ${Math.abs(a)}`, poles: [a, a], zeros: [0] };
    },
  },
  {
    name: "aⁿ · u[n]  (geometric sequence)",
    tableNum: "1", tableDen: "1 − az⁻¹",
    re: /^(-?\d+\.?\d*)\^n\*u\[n\]$/,
    build: (m) => {
      const a = parseFloat(m[1]);
      return { params: `a = ${a}`, num: `z`, den: `z − ${a}`, roc: `|z| > ${Math.abs(a)}`, poles: [a], zeros: [0] };
    },
  },
  {
    name: "u[n]  (unit step)",
    tableNum: "1", tableDen: "1 − z⁻¹",
    re: /^u\[n\]$/,
    build: () => ({ params: ``, num: `z`, den: `z − 1`, roc: `|z| > 1`, poles: [1], zeros: [0] }),
  },
  {
    name: "δ[n]  (unit impulse)",
    tableNum: "1", tableDen: "",
    re: /^(delta|d)\[n\]$/,
    build: () => ({ params: ``, num: `1`, den: ``, roc: `all z`, poles: [], zeros: [] }),
  },
];

function solveZTerm(rawTerm) {
  const cleaned = rawTerm.replace(/\s+/g, "");
  const { coeff, rest } = extractCoefficient(cleaned);
  for (const rule of Z_RULES) {
    const m = rest.match(rule.re);
    if (m) return { ok: true, coeff, rule, built: rule.build(m), rest };
  }
  return { ok: false, coeff, rest };
}

function PoleZeroPlot({ poles, zeros }) {
  const circlePts = Array.from({ length: 65 }, (_, i) => {
    const a = (i / 64) * 2 * Math.PI;
    return { x: Math.cos(a), y: Math.sin(a) };
  });
  const maxExtent = Math.max(1.4, ...poles.map((p) => Math.abs(p) + 0.4), ...zeros.map((z) => Math.abs(z) + 0.4));

  return (
    <div style={{ width: "100%", height: 200 }}>
      <ResponsiveContainer>
        <ComposedChart margin={{ top: 10, right: 10, bottom: 0, left: -10 }}>
          <CartesianGrid stroke={COLORS.foam} />
          <XAxis type="number" dataKey="x" domain={[-maxExtent, maxExtent]} tick={{ fontSize: 9, fill: COLORS.deep }} />
          <YAxis type="number" dataKey="y" domain={[-maxExtent, maxExtent]} tick={{ fontSize: 9, fill: COLORS.deep }} />
          <Line data={circlePts} dataKey="y" stroke={COLORS.deep} strokeDasharray="3 3" dot={false} strokeWidth={1} type="monotone" />
          {poles.map((p, i) => (
            <ReferenceDot key={`p${i}`} x={p} y={0} r={6} fill="none" stroke="#C0392B" strokeWidth={2} />
          ))}
          {zeros.map((z, i) => (
            <ReferenceDot key={`z${i}`} x={z} y={0} r={5} fill={COLORS.ocean} stroke="white" strokeWidth={1.5} />
          ))}
        </ComposedChart>
      </ResponsiveContainer>
      <div className="flex items-center justify-center gap-4 text-[10px] mt-1" style={{ color: COLORS.deep }}>
        <span>✕ red = pole</span>
        <span>● blue = zero</span>
        <span>dashed = unit circle</span>
      </div>
    </div>
  );
}

function ZTransform({ onBack }) {
  const [input, setInput] = useState("u[n] - 0.5^n*u[n]");
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");
  const inputRef = useRef(null);

  function insertAtCursor(snippet, cursorOffset) {
    const el = inputRef.current;
    const start = el ? el.selectionStart : input.length;
    const end = el ? el.selectionEnd : input.length;
    const newVal = input.slice(0, start) + snippet + input.slice(end);
    setInput(newVal);
    requestAnimationFrame(() => {
      if (el) {
        const pos = start + (cursorOffset ?? snippet.length);
        el.focus();
        el.setSelectionRange(pos, pos);
      }
    });
  }

  const Z_SYMBOLS = [
    { label: "+", insert: " + " },
    { label: "−", insert: " - " },
    { label: "×", insert: "*" },
    { label: "n", insert: "n" },
    { label: "aⁿ", insert: "^n" },
    { label: "u[n]", insert: "u[n]" },
    { label: "δ[n]", insert: "delta[n]" },
    { label: "( )", insert: "()", cursorOffset: 1 },
  ];

  function handleSolve() {
    setError("");
    const cleanedExpr = input.replace(/\s+/g, "");
    if (!cleanedExpr) { setError("Enter a sequence first."); setResult(null); return; }
    const rawTerms = splitTopLevel(cleanedExpr);
    const solved = rawTerms.map((t) => ({ sign: t.sign, ...solveZTerm(t.text) }));
    const anyFail = solved.find((s) => !s.ok);
    if (anyFail) {
      setError(`Couldn't recognize term: "${anyFail.rest || anyFail.text}". Try forms like u[n], 0.5^n*u[n], n*0.8^n*u[n], delta[n].`);
      setResult(null); return;
    }
    setResult({ terms: solved, multi: solved.length > 1 });
  }

  const allPoles = result ? result.terms.flatMap((t) => t.built.poles) : [];
  const allZeros = result ? result.terms.flatMap((t) => t.built.zeros) : [];

  return (
    <div className="w-full max-w-sm mx-auto overflow-hidden flex flex-col" style={SCREEN_SHELL}>
      <ScreenHeader moduleNum={6} title="Z-Transform" onBack={onBack} />
      <div className="px-6 flex-1 overflow-y-auto pb-6">
        <div className="rounded-2xl p-4 mb-4 relative overflow-hidden text-white"
          style={{ background: `linear-gradient(150deg, ${COLORS.navy} 0%, #142E7A 100%)`, borderRadius: "22px 22px 22px 6px" }}>
          <div className="absolute rounded-full" style={{ width: 70, height: 70, background: "rgba(255,255,255,0.10)", top: -25, right: -20 }} />
          <div className="relative flex items-center gap-2 mb-2">
            <RadioTower size={16} />
            <span className="text-xs font-semibold tracking-wide uppercase opacity-90">x[n] =</span>
          </div>
          <div className="relative rounded-xl px-3 py-2 mb-2" style={{ backgroundColor: "rgba(255,255,255,0.10)" }}>
            <span className="text-[9px] uppercase tracking-wide opacity-60 block mb-0.5">Preview</span>
            <MathPreview text={input} />
          </div>
          <input ref={inputRef} value={input} onChange={(e) => setInput(e.target.value)} placeholder="e.g. u[n] - 0.5^n*u[n]"
            className="relative w-full px-3 py-2 rounded-xl text-sm font-mono outline-none text-white"
            style={{ backgroundColor: "rgba(255,255,255,0.15)" }} />
          <div className="relative flex flex-wrap gap-1.5 mt-2">
            {Z_SYMBOLS.map((s) => (
              <button key={s.label} type="button" onClick={() => insertAtCursor(s.insert, s.cursorOffset)}
                className="px-2.5 py-1 rounded-lg text-xs font-mono font-semibold"
                style={{ backgroundColor: "rgba(255,255,255,0.18)", color: "white" }}>
                {s.label}
              </button>
            ))}
          </div>
          <p className="relative text-[11px] mt-2 opacity-75">Tap a symbol to insert it at your cursor — write it like you would on paper.</p>
          <button onClick={handleSolve} className="relative flex items-center justify-center gap-1 w-full mt-3 py-2 rounded-xl text-sm font-semibold" style={{ backgroundColor: COLORS.ocean }}>
            <Play size={14} /> Solve
          </button>
        </div>

        {error && (
          <div className="rounded-xl p-3 mb-4 flex items-start gap-2" style={{ backgroundColor: "#FDEAEA" }}>
            <AlertCircle size={16} style={{ color: "#C0392B", marginTop: 1 }} />
            <p className="text-xs" style={{ color: "#C0392B" }}>{error}</p>
          </div>
        )}

        {result && (
          <div className="space-y-3">
            {result.multi && (
              <div className="rounded-xl p-3" style={{ backgroundColor: COLORS.foam }}>
                <p className="text-xs font-semibold" style={{ color: COLORS.navy }}>Step 1 — Apply Linearity</p>
                <p className="text-xs mt-1" style={{ color: COLORS.deep }}>
                  Z{"{x[n] + y[n]}"} = X(z) + Y(z) — solve each term, then sum. Overall ROC = intersection of each term's ROC.
                </p>
              </div>
            )}
            {result.terms.map((t, i) => (
              <div key={i} className="rounded-2xl p-4" style={{ backgroundColor: "white", boxShadow: "0 2px 8px rgba(13,46,146,0.08)" }}>
                <p className="text-xs font-semibold" style={{ color: COLORS.ocean }}>
                  {result.multi ? `Term ${i + 1}` : "Solving"}: {t.sign === "-" ? "−" : ""}{t.coeff !== 1 ? t.coeff + "·" : ""}{t.rest || t.text}
                </p>
                <p className="text-[11px] mt-2" style={{ color: COLORS.deep }}>Rule: {t.rule.name}</p>
                <div className="flex items-center gap-2 mt-2 flex-wrap">
                  <span className="text-xs font-mono" style={{ color: COLORS.deep }}>Table:</span>
                  <Fraction num={t.rule.tableNum} den={t.rule.tableDen} color={COLORS.deep} />
                </div>
                <div className="mt-2 rounded-lg p-3 flex items-center justify-center gap-1" style={{ backgroundColor: COLORS.foam }}>
                  {t.sign === "-" && <span className="font-mono text-sm" style={{ color: COLORS.navy }}>−</span>}
                  {t.coeff !== 1 && <span className="font-mono text-sm" style={{ color: COLORS.navy }}>{t.coeff}·</span>}
                  <Fraction num={t.built.num} den={t.built.den} color={COLORS.navy} />
                </div>
                <p className="text-[11px] mt-2 text-center font-mono" style={{ color: COLORS.deep }}>ROC: {t.built.roc}</p>
              </div>
            ))}

            <div className="rounded-2xl p-4" style={{ background: `linear-gradient(150deg, ${COLORS.deep} 0%, ${COLORS.navy} 100%)`, borderRadius: "22px 22px 22px 6px" }}>
              <p className="text-[11px] uppercase tracking-wide text-white/70 text-center mb-2">Result X(z)</p>
              <div className="flex items-center justify-center flex-wrap gap-1">
                {result.terms.map((t, i) => (
                  <React.Fragment key={i}>
                    <span className="font-mono text-sm text-white">
                      {i === 0 ? (t.sign === "-" ? "−" : "") : (t.sign === "-" ? "−" : "+")}
                      {t.coeff !== 1 ? `${t.coeff}·` : ""}
                    </span>
                    <Fraction num={t.built.num} den={t.built.den} color="white" />
                  </React.Fragment>
                ))}
              </div>
            </div>

            <div className="rounded-2xl p-4" style={{ backgroundColor: "white", boxShadow: "0 2px 8px rgba(13,46,146,0.08)" }}>
              <span className="text-xs font-semibold uppercase tracking-wide" style={{ color: COLORS.ocean }}>Pole-Zero Plot</span>
              <PoleZeroPlot poles={allPoles} zeros={allZeros} />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ============ APP ROOT / ROUTER ============ */
export default function DSPToolkitApp() {
  const [screen, setScreen] = useState("home");

  const goHome = () => setScreen("home");

  switch (screen) {
    case "dacadc": return <DACADCConverter onBack={goHome} />;
    case "laplace": return <LaplaceTransform onBack={goHome} />;
    case "ztransform": return <ZTransform onBack={goHome} />;
    case "diffeq": return <DifferenceEquation onBack={goHome} />;
    case "convolution": return <Convolution onBack={goHome} />;
    case "dtfs": return <DTFS onBack={goHome} />;
    case "filters": return <Filters onBack={goHome} />;
    case "freqdomain": return <FrequencyDomain onBack={goHome} />;
    case "hero": return <HeroScreen onNavigate={setScreen} />;
    case "profile": return <ProfileScreen onNavigate={setScreen} />;
    default: return <HomeScreen onNavigate={setScreen} />;
  }
}
